<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $product->name }} — TeknoTemu</title><style>:root{--ink:#1A4230;--blue:#1A4230;--yellow:#F0402A;--page:#EFE3CA;--line:#1A423033;--muted:#1A4230aa}.gallery{display:grid;grid-template-columns:76px 1fr;gap:12px}.thumbs{display:grid;align-content:start;gap:8px}.thumb{border:2px solid transparent;border-radius:9px;padding:3px;background:#EFE3CA;cursor:pointer}.thumb.active{border-color:var(--blue)}.thumb img{width:100%;height:62px;object-fit:cover;border-radius:6px}.media-main{min-width:0}.media-main img,.media-main video{width:100%;height:420px;object-fit:contain;background:#EFE3CA;border-radius:18px}.media-main video{object-fit:contain}.media-label{display:block;margin:8px 0 0;font-size:11px;color:var(--muted);text-align:center}@media(max-width:700px){.gallery{grid-template-columns:1fr}.thumbs{grid-template-columns:repeat(5,1fr);order:2}.media-main img,.media-main video{height:290px}}*{box-sizing:border-box}body{margin:0;background:var(--page);color:var(--ink);font:15px/1.5 Inter,system-ui,sans-serif}a,button{cursor:pointer}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.skip-link{position:absolute;left:16px;top:-50px;background:var(--ink);color:#EFE3CA;padding:10px 14px;border-radius:8px;z-index:20}.skip-link:focus{top:16px}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--yellow);outline-offset:3px}.header{height:76px;background:#EFE3CAdd;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:28px;padding:0 clamp(20px,5vw,76px);position:sticky;top:0;z-index:5;backdrop-filter:blur(12px)}.brand{font-size:22px;font-weight:900;letter-spacing:-1px;text-decoration:none;color:var(--ink);white-space:nowrap}.brand span{color:var(--blue)}.search{display:flex;max-width:480px;flex:1;margin:auto}.search input{width