mall{display:block;margin-top:9px}.related-card b{font-size:14px}.related-card small{color:var(--muted);font-size:12px}footer{margin-top:80px;padding:28px clamp(20px,5vw,76px);background:var(--blue);color:#EFE3CA;display:flex;gap:28px;flex-wrap:wrap;font-size:12px}footer b{color:var(--yellow)}footer span{color:#EFE3CA}@media(max-width:700px){.top{height:auto;flex-wrap:wrap;padding:14px 20px;gap:10px}.search{order:3;flex-basis:100%}.category-nav{padding:12px 20px}.wrap{padding:0 16px 35px}.product{grid-template-columns:1fr;padding:18px;margin-top:22px}.photo{min-height:280px}}
</style></head><body>@include('partials.site-header')<div class="wrap"><main class="product">@php $media = array_values(array_unique(array_filter(array_merge([$product->image_url], $product->gallery_urls ?? [])))); @endphp<div class="photo"><div class="gallery"><div class="thumbs">@foreach($media as $i => $url)<button class="thumb {{ $i === 0 ? 'active' : '' }}" type="button" data-media="{{ $url }}" aria-label="Lihat foto {{ $i + 1 }}"><img src="{{ $url }}" alt=""></button>@endforeach @if ($product->video_url) <button class="thumb" type="button" data-video="{{ $product->video_url }}" aria-label="Putar video produk">Video</button> @endif</div><div class="media-main"><img id="mainMedia" src="{{ $media[0] ?? 'https://placehold.co/600x600/e5eef9/081c48?text=Produk' }}" alt="{{ $product->name }}"><video id="mainVideo" controls hidden></video><small class="media-label">{{ count($media) }} foto{{ $product->video_url ? ' + video' : '' }}</small></div></div></div><div><p class="eyebrow">{{ $product->category }}</p><h1 class="title">{{ $product->name }}</h1><p class="muted">{{ $product->brand }} · {{ number_format($product->sold_count) }} terjual</p><div class="price">Rp {{ number_format($product->price_idr, 0, ',', '.') }}</div><div class="spec"><b>Spesifikasi pilihan</b><br>{{ $product->spec ?: 'Spesifikasi tersedia di marketplace.' }}</div><a class="buy" href="{{ $product->affiliate_url }}" target="_blank" rel="sponsored nofollow noopener">Buka di Shopee ↗</a><p class="notice">Harga dan stok dapat berubah. Cek ulang di Shopee sebelum membeli. TeknoTemu dapat menerima komisi dari pembelian melalui link ini.</p></div></main>@if($recommendations->isNotEmpty())<section class="related"><h2>Rekomendasi sejenis</h2><div class="related-grid">@foreach($recommendations as $item)<a class="related-card" href="{{ route('products.show', $item) }}"><img src="{{ $item->image_url ?: 'https://placehold.co/300x220/e5eef9/081c48?text=Produk' }}" alt="{{ $item->name }}"><div><b>{{ $item->name }}</b><small>{{ $item->brand }} · Rp {{ number_format($item->price_idr, 0, ',', '.') }}</small></div></a>@endforeach</div></section>@endif</div>@include('partials.site-footer')<script>const mainMedia=document.getElementById('mainMedia'),mainVideo=document.getElementById('mainVideo');document.querySelectorAll('[data-media]').forEach(btn=>btn.onclick=()=>{mainMedia.src=btn.dataset.media;mainMedia.hidden=false;mainVideo.hidden=true;document.querySelectorAll('.thumb').forEach(x=>x.classList.toggle('active',x===btn))});document.querySelectorAll('[data-video]').forEach(btn=>btn.onclick=()=>{mainVideo.src=btn.dataset.video;mainVideo.hidden=false;mainMedia.hidden=true;document.querySelectorAll('.thumb').forEach(x=>x.classList.toggle('active',x===btn));mainVideo.play().catch(()=>{})});</script></body></html>